// ReliefWeb returns one entry per disaster, each carrying its country list.
// We aggregate to a per-country active-disaster count, which is the signal the
// scoring function consumes.
const observedAt = new Date().toISOString().slice(0, 10);
const body = $input.first().json;

// An unregistered appname returns 403 with an error object rather than data.
// Name that case explicitly so it does not read as a generic parse failure.
if (body?.status === 403 || body?.error?.type === 'AccessDeniedHttpException') {
  throw new Error(
    'ReliefWeb rejected the appname "' + ($env.RELIEFWEB_APPNAME ?? '') + '". ' +
    'It must be registered at https://apidoc.reliefweb.int/parameters#appname'
  );
}

const entries = body?.data;
if (!Array.isArray(entries)) {
  throw new Error('ReliefWeb returned an unexpected shape — no data array present.');
}

const counts = new Map();

for (const entry of entries) {
  const countries = entry?.fields?.country ?? [];
  for (const country of countries) {
    // ReliefWeb uses ISO3 in `iso3`, lowercase in some responses.
    const iso3 = String(country?.iso3 ?? '').toUpperCase();
    if (iso3.length !== 3) continue;
    counts.set(iso3, (counts.get(iso3) ?? 0) + 1);
  }
}

if (counts.size === 0) {
  throw new Error('ReliefWeb returned no disasters with a usable ISO3 country code.');
}

const observations = [...counts.entries()].map(([iso3, count]) => ({
  iso3,
  source: 'reliefweb',
  metric: 'active_disaster_count',
  value: count,
  observedAt,
}));

// Countries the API does not know are dropped by the API, not here — it
// reports them as warnings so data-quality drift stays visible.
return [{ json: { source: 'reliefweb', observations, triggerScoring: false } }];
